INSERT INTO fault_codes (controller_id, code, title, description, is_safety_related, source)
SELECT c.id, v.code, v.title, v.description, v.safety, c.doc_ref
FROM controllers c
JOIN (
    SELECT '09' AS code, 'Ключ ППП замкнут вне режима пожарной опасности' AS title, 'Попытка включить перевозку пожарных подразделений ключом ППП не из режима пожарной опасности. УЛ аварийно останавливает лифт, на индикаторе периодически появляется 09. Для возврата в работу нужно вынуть ключ и переключить тумблер SA1 «Сеть» в УЛ.' AS description, 1 AS safety
    UNION ALL SELECT '41' AS code, 'Нет питания +24 В' AS title, 'Пропало напряжение +24 В, все цепи +24 В обесточены, индикатор +24 В на плате ПТЗ не светится. Лифт возвращается в работу после восстановления номинального напряжения источника.' AS description, 0 AS safety
    UNION ALL SELECT '42' AS code, 'Одновременно сигналы датчиков точной остановки и замедления' AS title, 'УЛ во всех режимах контролирует, что датчики точной остановки (ДТО, ДТО2) и замедления (ДЗ, ДЗ-1) не срабатывают одновременно. Код появляется, если сигналы пришли вместе. Лифт возвращается в работу после устранения неисправности.' AS description, 0 AS safety
    UNION ALL SELECT '43' AS code, 'Разомкнута цепь аппаратов безопасности' AS title, 'В режимах МП2 и РЕВИЗИЯ размыкание любого контакта цепи безопасности сразу останавливает кабину, реле К1 «АВАРИЯ» выключается. В режимах с большой скоростью разрыв короче 2 секунд считается кратковременным сбоем и только заносится в память. Если цепь разомкнута дольше 2 секунд, рядом с 43 записывается 44 и лифт аварийно останавливается. После восстановления цепи работоспособность возвращается кратковременным переключением в режим МП2. При закрытых дверях состояние цепи видно по светодиодам HL13-HL16 на плате ПУ.' AS description, 1 AS safety
    UNION ALL SELECT '44' AS code, 'Охрана шахты: аварийный останов' AS title, 'УЛ формирует код только в режимах с движением на большой скорости и аварийно останавливает лифт. Рядом с 44 в память обычно записывается код-подсказка, уточняющий причину (таблица Д.1 руководства). Основные причины: несанкционированное открытие дверей шахты или кабины, разрыв цепи безопасности дольше 2 секунд, искусственные перемычки в блокировочных цепях дверей.' AS description, 1 AS safety
    UNION ALL SELECT '45' AS code, 'Нет готовности преобразователя частоты' AS title, 'Пропал сигнал готовности привода от преобразователя частоты: нет +24 В на входе Х5:8 платы ПУ, либо пропали сигналы 012 и 013 при движении. Лифт восстанавливает работу после устранения неисправности. В методике проверки контроля колодок тормоза (РЭ лифта 0401К) при отключённом проводе КТА или КТВ именно так проявляется авария: в ПЧ Hpmont ошибка E36, в УЛ код 45.' AS description, 0 AS safety
    UNION ALL SELECT '46' AS code, 'Разомкнута блокировочная цепь контроля дверей кабины' AS title, 'УЛ фиксирует разрыв цепи безопасности дверей кабины по пропаданию 110 В на входе X6:1 (цепь 64) платы ПУ при замкнутой цепи безопасности. В режимах РЕВИЗИЯ и МП2 движущаяся кабина сразу останавливается. В режимах с большой скоростью разрыв дольше 2 секунд меняет 46 на 44 (аварийный останов). Если кабина стоит в зоне точной остановки в автоматическом режиме, двери реверсируются, а на индикаторе многократно появляется 46. При разрыве цепи в движении дополнительно записывается код 55, возможно отключение автомата QF1.' AS description, 1 AS safety
    UNION ALL SELECT '47' AS code, 'Сработала тепловая защита главного двигателя' AS title, 'На индикаторе периодически появляется 47. Нормальная работа восстанавливается после устранения неисправности или остывания двигателя.' AS description, 0 AS safety
    UNION ALL SELECT '48' AS code, 'Восемь реверсов дверей подряд' AS title, 'Многократное реверсирование дверей возможно только у неподвижной кабины в зоне точной остановки. После восьмого реверса процесс прекращается, двери остаются открытыми, лифт выходит из группового управления, приказы сбрасываются. Через 30-40 секунд сигнал уходит диспетчеру, затем каждые 9-10 минут повторяется пробное закрытие. Система возвращается в работу, когда замкнутся блокировочные цепи дверей шахты и кабины.' AS description, 0 AS safety
    UNION ALL SELECT '49' AS code, 'Превышено контрольное время открытия дверей' AS title, 'В режимах ПОГРУЗКА и НОРМАЛЬНАЯ РАБОТА при превышении времени привод дверей переключается на закрытие и затем снова на открытие. Если и тогда время превышено, формируется 49 и лифт аварийно останавливается. Контрольное время задаётся параметром программирования А7. Лифт возвращается в работу после выключения питания и устранения неисправности.' AS description, 0 AS safety
    UNION ALL SELECT '50' AS code, 'Превышено контрольное время закрытия дверей' AS title, 'В режимах РЕВИЗИЯ, МП и МП1 контролируется только время закрытия, при превышении появляется 50 и лифт аварийно останавливается. Контрольное время задаётся параметром А7. Лифт возвращается в работу после выключения питания и устранения неисправности.' AS description, 0 AS safety
    UNION ALL SELECT '51' AS code, 'Четыре неудачных пуска подряд из зоны точной остановки' AS title, 'После четырёх подряд неудачных попыток начать движение на большой скорости появляется 51 и лифт аварийно останавливается. В памяти обычно цепочка 51, 52, 52, 52. Лифт возвращается в работу после выключения питания и устранения неисправности.' AS description, 0 AS safety
    UNION ALL SELECT '52' AS code, 'Превышено время нахождения в зоне точной остановки при включённом приводе' AS title, 'Контроль идёт только в режимах с большой скоростью. Если при разомкнутой цепи обратной связи пускателей главного привода кабина остаётся в зоне точной остановки дольше 4 секунд, в память записывается 52. Лифт возвращается в работу после выключения питания и устранения неисправности.' AS description, 0 AS safety
    UNION ALL SELECT '53' AS code, 'Превышено время движения между соседними остановками' AS title, 'Измеряется время между двумя срабатываниями ДТО при движении, контроль только в режимах с большой скоростью. Контрольное время меняется параметром программирования А5. Лифт аварийно останавливается и возвращается в работу после выключения питания и устранения неисправности.' AS description, 0 AS safety
    UNION ALL SELECT '54' AS code, 'Переключатель «НР-РЕВ» в положении «РЕВ» без режима РЕВИЗИЯ' AS title, 'Переключатель на посту ревизии переведён в «РЕВ», а режим РЕВИЗИЯ в УЛ не установлен. Лифт возвращается в работу, когда переключатель поставлен в положение «НР».' AS description, 0 AS safety
    UNION ALL SELECT '55' AS code, 'Разрыв блокировочной цепи дверей кабины в движении' AS title, 'Уточняющий код к 46: цепь контроля дверей кабины разомкнулась именно во время движения. Пускатели главного привода отключаются сразу, реле К1 выключается, возможно отключение автомата QF1.' AS description, 1 AS safety
    UNION ALL SELECT '56' AS code, 'Нет сигнала о выключении пускателей главного привода' AS title, 'Без команд на включение пускателей цепь их обратной связи осталась разомкнутой. УЛ останавливает лифт и выключает реле К1, на индикаторе периодически появляется 56. В автоматических режимах обычно проявляется по прибытии на этаж, двери остаются закрытыми. Лифт возвращается в работу после устранения неисправности.' AS description, 1 AS safety
    UNION ALL SELECT '57' AS code, 'Нет сигнала о выключении стопорного устройства' AS title, 'Код описан в руководстве только заголовком. Подробности смотрите в РЭ.' AS description, 1 AS safety
    UNION ALL SELECT '58' AS code, 'Нажата кнопка «ОТМЕНА»' AS title, 'Только для пассажирских лифтов. Фиксируется при нажатии кнопки и заносится в память.' AS description, 0 AS safety
    UNION ALL SELECT '59' AS code, 'Одновременно сработали контакты ВКО и ВКЗ' AS title, 'Контроль идёт во всех режимах, независимо от движения кабины. УЛ останавливает работу лифта. Лифт возвращается в работу после устранения неисправности.' AS description, 0 AS safety
    UNION ALL SELECT '60' AS code, 'Строка матрицы М0 закорочена на шину -L' AS title, 'Контроль во всех режимах, доступ к сервисным функциям запрещается. Для поиска причины выключить вводное устройство, отсоединить от платы ПУ разъём X16 и прозвонить относительно шины -L цепи 501-508. Если внешние цепи исправны, вероятнее всего неисправна плата ПУ.' AS description, 0 AS safety
    UNION ALL SELECT '61' AS code, 'Нет опросных импульсов строки Str1 матрицы М0' AS title, 'Не формируются опросные импульсы строки 1 (Str1) матрицы М0. Контроль во всех режимах работы. Наиболее вероятная причина: неисправна плата ПУ.' AS description, 0 AS safety
    UNION ALL SELECT '62' AS code, 'Нет опросных импульсов строки Str2 матрицы М0' AS title, 'Не формируются опросные импульсы строки 2 (Str2) матрицы М0. Контроль во всех режимах работы. Наиболее вероятная причина: неисправна плата ПУ.' AS description, 0 AS safety
    UNION ALL SELECT '63' AS code, 'Нет опросных импульсов строки Str3 матрицы М0' AS title, 'Не формируются опросные импульсы строки 3 (Str3) матрицы М0. Контроль во всех режимах работы. Наиболее вероятная причина: неисправна плата ПУ.' AS description, 0 AS safety
    UNION ALL SELECT '64' AS code, 'Нет опросных импульсов строки Str4 матрицы М0' AS title, 'Не формируются опросные импульсы строки 4 (Str4) матрицы М0. Контроль во всех режимах работы. Наиболее вероятная причина: неисправна плата ПУ.' AS description, 0 AS safety
    UNION ALL SELECT '65' AS code, 'Нет опросных импульсов строки Str5 матрицы М0' AS title, 'Не формируются опросные импульсы строки 5 (Str5) матрицы М0. Контроль во всех режимах работы. Наиболее вероятная причина: неисправна плата ПУ.' AS description, 0 AS safety
    UNION ALL SELECT '66' AS code, 'Нет опросных импульсов строки Str6 матрицы М0' AS title, 'Не формируются опросные импульсы строки 6 (Str6) матрицы М0. Контроль во всех режимах работы. Наиболее вероятная причина: неисправна плата ПУ.' AS description, 0 AS safety
