    UNION ALL SELECT '68' AS code, 'Нет опросных импульсов строки Str8 матрицы М0' AS title, 'Не формируются опросные импульсы строки 8 (Str8) матрицы М0. Контроль во всех режимах работы. Наиболее вероятная причина: неисправна плата ПУ.' AS description, 0 AS safety
    UNION ALL SELECT '70' AS code, 'Строка матрицы М1 закорочена на шину -L' AS title, 'Контроль только в режиме НОРМАЛЬНАЯ РАБОТА. Одиночный лифт или все лифты группы переводятся в режим «УТРЕННИЙ»: работают только по приказам, затем кабина уезжает на посадочный этаж и стоит с открытой дверью. В группе код 70 не высвечивается, а заносится в память, на индикаторах всех плат ПУ показывается A1.' AS description, 0 AS safety
    UNION ALL SELECT '71' AS code, 'Нет опросных импульсов строки Str1 матрицы М1' AS title, 'Не формируются опросные импульсы строки 1 (Str''1) матрицы М1. В группе контроль ведёт только ведущий лифт: при ошибке он передаёт управление группой другому лифту. Одиночный лифт показывает ошибку постоянно, вызывные кнопки неисправной строки не регистрируются.' AS description, 0 AS safety
