    UNION ALL SELECT '73' AS code, 'Нет опросных импульсов строки Str3 матрицы М1' AS title, 'Не формируются опросные импульсы строки 3 (Str''3) матрицы М1. В группе контроль ведёт только ведущий лифт: при ошибке он передаёт управление группой другому лифту. Одиночный лифт показывает ошибку постоянно, вызывные кнопки неисправной строки не регистрируются.' AS description, 0 AS safety
