    UNION ALL SELECT '75' AS code, 'Нет опросных импульсов строки Str5 матрицы М1' AS title, 'Не формируются опросные импульсы строки 5 (Str''5) матрицы М1. В группе контроль ведёт только ведущий лифт: при ошибке он передаёт управление группой другому лифту. Одиночный лифт показывает ошибку постоянно, вызывные кнопки неисправной строки не регистрируются.' AS description, 0 AS safety
    UNION ALL SELECT '76' AS code, 'Нет опросных импульсов строки Str6 матрицы М1' AS title, 'Не формируются опросные импульсы строки 6 (Str''6) матрицы М1. В группе контроль ведёт только ведущий лифт: при ошибке он передаёт управление группой другому лифту. Одиночный лифт показывает ошибку постоянно, вызывные кнопки неисправной строки не регистрируются.' AS description, 0 AS safety
    UNION ALL SELECT '77' AS code, 'Нет опросных импульсов строки Str7 матрицы М1' AS title, 'Не формируются опросные импульсы строки 7 (Str''7) матрицы М1. В группе контроль ведёт только ведущий лифт: при ошибке он передаёт управление группой другому лифту. Одиночный лифт показывает ошибку постоянно, вызывные кнопки неисправной строки не регистрируются.' AS description, 0 AS safety
    UNION ALL SELECT '78' AS code, 'Нет опросных импульсов строки Str8 матрицы М1' AS title, 'Не формируются опросные импульсы строки 8 (Str''8) матрицы М1. В группе контроль ведёт только ведущий лифт: при ошибке он передаёт управление группой другому лифту. Одиночный лифт показывает ошибку постоянно, вызывные кнопки неисправной строки не регистрируются.' AS description, 0 AS safety
    UNION ALL SELECT '79' AS code, 'Сигнал датчика загрузки 110 % без сигнала 90 %' AS title, 'Только пассажирские лифты. В режимах МП2, РЕВИЗИЯ и МП1 код на работу лифта не влияет.' AS description, 0 AS safety
    UNION ALL SELECT '80' AS code, 'Неисправно ОЗУ платы ПУ' AS title, 'Неисправна микросхема ОЗУ DD13 на плате ПУ. Контроль выполняется при включении платы во всех режимах.' AS description, 0 AS safety
    UNION ALL SELECT '81' AS code, 'Столбец Stb1 матрицы М0 закорочен на шину -L' AS title, 'Информационный столбец Stb1 (601) закорочен на шину -L. Кнопки приказов, подключённые к этому столбцу, не регистрируются. Для поиска: выключить УЛ и вводное устройство, отсоединить разъём X12 от платы ПУ и прозвонить относительно шины -L цепь 601.' AS description, 0 AS safety
    UNION ALL SELECT '82' AS code, 'Столбец Stb2 матрицы М0 закорочен на шину -L' AS title, 'Информационный столбец Stb2 (602) закорочен на шину -L. Кнопки приказов, подключённые к этому столбцу, не регистрируются. Для поиска: выключить УЛ и вводное устройство, отсоединить разъём X12 от платы ПУ и прозвонить относительно шины -L цепь 602.' AS description, 0 AS safety
    UNION ALL SELECT '83' AS code, 'Столбец Stb3 матрицы М0 закорочен на шину -L' AS title, 'Информационный столбец Stb3 (603) закорочен на шину -L. Кнопки приказов, подключённые к этому столбцу, не регистрируются. Для поиска: выключить УЛ и вводное устройство, отсоединить разъём X12 от платы ПУ и прозвонить относительно шины -L цепь 603.' AS description, 0 AS safety
    UNION ALL SELECT '84' AS code, 'Столбец Stb4 матрицы М0 закорочен на шину -L' AS title, 'Информационный столбец Stb4 (604) закорочен на шину -L. Кнопки приказов, подключённые к этому столбцу, не регистрируются. Для поиска: выключить УЛ и вводное устройство, отсоединить разъём X12 от платы ПУ и прозвонить относительно шины -L цепь 604.' AS description, 0 AS safety
    UNION ALL SELECT '85' AS code, 'Столбец Stb5 матрицы М0 закорочен на шину -L' AS title, 'Информационный столбец Stb5 (605) закорочен на шину -L. УЛ остановило работу лифта и запретило сервисную функцию F7. Для поиска: выключить УЛ и вводное устройство, отсоединить разъём X12 от платы ПУ и прозвонить относительно шины -L цепь 605.' AS description, 0 AS safety
    UNION ALL SELECT '86' AS code, 'Столбец Stb6 матрицы М0 закорочен на шину -L' AS title, 'Информационный столбец Stb6 (606) закорочен на шину -L. УЛ остановило работу лифта и запретило сервисную функцию F7. Для поиска: выключить УЛ и вводное устройство, отсоединить разъём X12 от платы ПУ и прозвонить относительно шины -L цепь 606.' AS description, 0 AS safety
    UNION ALL SELECT '87' AS code, 'Столбец Stb7 матрицы М0 закорочен на шину -L' AS title, 'Информационный столбец Stb7 (607) закорочен на шину -L. УЛ остановило работу лифта и запретило сервисную функцию F7. Для поиска: выключить УЛ и вводное устройство, отсоединить разъём X12 от платы ПУ и прозвонить относительно шины -L цепь 607.' AS description, 0 AS safety
    UNION ALL SELECT '88' AS code, 'Столбец Stb8 матрицы М0 закорочен на шину -L' AS title, 'Информационный столбец Stb8 (608) закорочен на шину -L. УЛ остановило работу лифта и запретило сервисную функцию F7. Для поиска: выключить УЛ и вводное устройство, отсоединить разъём X12 от платы ПУ и прозвонить относительно шины -L цепь 608.' AS description, 0 AS safety
    UNION ALL SELECT '89' AS code, 'Время между остановками меньше допустимого' AS title, 'Время между двумя срабатываниями ДТО меньше 1,7 с (0,5 с для лифтов с проходной кабиной). Контроль только в режимах с большой скоростью. УЛ аварийно останавливает лифт.' AS description, 0 AS safety
    UNION ALL SELECT '90' AS code, 'Нарушен контроль фаз питающей сети' AS title, 'При нарушении чередования фаз или обрыве фазы выход платы ПКТС даёт сигнал 0, индикатор «Контр. фаз» не светится, УЛ останавливает лифт. Лифт возвращается в работу при восстановлении параметров сети.' AS description, 0 AS safety
    UNION ALL SELECT '91' AS code, 'Столбец Stb''1 матрицы М1 закорочен на шину -L' AS title, 'Информационный столбец Stb''1 (801) матрицы М1 закорочен на шину -L. Вызывные кнопки, подключённые к этому столбцу, не регистрируются.' AS description, 0 AS safety
    UNION ALL SELECT '92' AS code, 'Столбец Stb''2 матрицы М1 закорочен на шину -L' AS title, 'Информационный столбец Stb''2 (802) матрицы М1 закорочен на шину -L. Вызывные кнопки, подключённые к этому столбцу, не регистрируются.' AS description, 0 AS safety
    UNION ALL SELECT '93' AS code, 'Столбец Stb''3 матрицы М1 закорочен на шину -L' AS title, 'Информационный столбец Stb''3 (803) матрицы М1 закорочен на шину -L. Вызывные кнопки, подключённые к этому столбцу, не регистрируются.' AS description, 0 AS safety
    UNION ALL SELECT '94' AS code, 'Столбец Stb''4 матрицы М1 закорочен на шину -L' AS title, 'Информационный столбец Stb''4 (804) матрицы М1 закорочен на шину -L. Вызывные кнопки, подключённые к этому столбцу, не регистрируются.' AS description, 0 AS safety
    UNION ALL SELECT '95' AS code, 'Столбец Stb''5 матрицы М1 закорочен на шину -L' AS title, 'Информационный столбец Stb''5 (805) матрицы М1 закорочен на шину -L. Вызывные кнопки, подключённые к этому столбцу, не регистрируются. Если закорочен столбец Stb''5, лифт без требований уезжает на посадочный этаж и стоит с открытой дверью.' AS description, 0 AS safety
    UNION ALL SELECT '96' AS code, 'Столбец Stb''6 матрицы М1 закорочен на шину -L' AS title, 'Информационный столбец Stb''6 (806) матрицы М1 закорочен на шину -L. Вызывные кнопки, подключённые к этому столбцу, не регистрируются.' AS description, 0 AS safety
    UNION ALL SELECT '97' AS code, 'Столбец Stb''7 матрицы М1 закорочен на шину -L' AS title, 'Информационный столбец Stb''7 (807) матрицы М1 закорочен на шину -L. Вызывные кнопки, подключённые к этому столбцу, не регистрируются.' AS description, 0 AS safety
    UNION ALL SELECT '98' AS code, 'Столбец Stb''8 матрицы М1 закорочен на шину -L' AS title, 'Информационный столбец Stb''8 (808) матрицы М1 закорочен на шину -L. Вызывные кнопки, подключённые к этому столбцу, не регистрируются.' AS description, 0 AS safety
    UNION ALL SELECT '99' AS code, 'Пожарная или сейсмическая опасность' AS title, 'Лифт автоматически переходит в режим ПОЖАРНАЯ ОПАСНОСТЬ из рабочих режимов по сигналу системы пожарной защиты здания, на индикаторе периодически появляется 99. Возврат возможен только после снятия сигнала и переключения тумблера SA1 «Сеть» в УЛ.' AS description, 1 AS safety
    UNION ALL SELECT 'A0' AS code, 'Сбой местоположения кабины' AS title, 'УЛ считает этажи по срабатываниям ДТО. Код появляется, когда по счёту кабина пришла на нижний или верхний этаж, но сигнала датчика нижнего или верхнего этажа (ДНЭ, ДВЭ) нет. В режимах РЕВИЗИЯ и МП2 кабина не останавливается, на индикаторе FF. В режимах с большой скоростью кабина замедляется и останавливается на ближайшем этаже, приказы сбрасываются, лифт выходит из группы, затем выполняется корректировочный рейс.' AS description, 0 AS safety
    UNION ALL SELECT 'A1' AS code, 'Неисправен последовательный канал' AS title, 'Относится к групповому управлению, одиночный лифт код не контролирует. Лифт обслуживает только приказы, после исполнения уезжает на посадочный этаж и стоит с открытой дверью. Возвращается в нормальный режим после устранения неисправности.' AS description, 0 AS safety
    UNION ALL SELECT 'A2' AS code, 'Двери шахты открыты дольше контрольного времени' AS title, 'В режимах НОРМАЛЬНАЯ РАБОТА и ВЕЧЕРНИЙ контролируется время стоянки с открытыми дверями, порог 30 секунд. Приказы сбрасываются, лифт выходит из группы, реле К2 «ДИСПЕТЧЕРИЗАЦИЯ» выключается, К1 «АВАРИЯ» остаётся включённым. Возврат в работу после устранения неисправности.' AS description, 0 AS safety
    UNION ALL SELECT 'A3' AS code, 'Пропадание посылок в последовательном канале' AS title, 'Группа лифтов. Одиночный лифт не контролирует. Лифт обслуживает только приказы, после исполнения уезжает на посадочный этаж и стоит с открытой дверью. Возврат в нормальный режим после устранения неисправности.' AS description, 0 AS safety
    UNION ALL SELECT 'A4' AS code, 'Искажение посылок в последовательном канале' AS title, 'Группа лифтов. Как правило, неисправна плата ПУ. Лифт выходит из группы и обслуживает только приказы, возвращается в режим НОРМАЛЬНАЯ РАБОТА после устранения неисправности.' AS description, 0 AS safety
    UNION ALL SELECT 'A6' AS code, 'Одновременно сигналы датчиков нижнего и верхнего этажа' AS title, 'Если кабина в зоне нижнего или верхнего этажа, неисправен датчик ДНЭ или ДВЭ. Лифт возвращается в работу после устранения неисправности.' AS description, 0 AS safety
    UNION ALL SELECT 'A8' AS code, 'Нет импульсов от устройства контроля скорости УКС1' AS title, 'Только регулируемый привод в системе без шунтов и датчиков замедления. Контроль в режимах с большой скоростью. Кабина идёт на крайний этаж по направлению движения, замедляется по ДНЭ или ДВЭ и останавливается в зоне точной остановки, при пассажире двери открываются и остаются открытыми.' AS description, 0 AS safety
    UNION ALL SELECT 'A9' AS code, 'Нет калибровки' AS title, 'Показывается в режимах НОРМАЛЬНАЯ РАБОТА и ПОГРУЗКА. Появляется, если систему перевели на работу без шунтов и датчиков замедления (параметр С1 равен 1), а калибровочный рейс не выполнен.' AS description, 0 AS safety
    UNION ALL SELECT 'b0' AS code, 'Неисправность матрицы М0' AS title, 'Развязывающий диод в одном из узлов матрицы М0 потерял вентильные свойства или установлен неправильно.' AS description, 0 AS safety
    UNION ALL SELECT 'b1' AS code, 'Неисправен элемент гальванической развязки столбца Stb1' AS title, 'Элемент развязки столбца Stb1 (601) на плате ПУ постоянно закрыт, приказы этого столбца не регистрируются. Руководство называет возможные причины: оптопара, обрыв в цепи развязывающего диода, оптопара VU37 или транзистор VT42.' AS description, 0 AS safety
    UNION ALL SELECT 'b2' AS code, 'Неисправен элемент гальванической развязки столбца Stb2' AS title, 'Элемент развязки столбца Stb2 (602) на плате ПУ постоянно закрыт, приказы этого столбца не регистрируются. Руководство называет возможные причины: оптопара, обрыв в цепи развязывающего диода, оптопара VU37 или транзистор VT42.' AS description, 0 AS safety
    UNION ALL SELECT 'b3' AS code, 'Неисправен элемент гальванической развязки столбца Stb3' AS title, 'Элемент развязки столбца Stb3 (603) на плате ПУ постоянно закрыт, приказы этого столбца не регистрируются. Руководство называет возможные причины: оптопара, обрыв в цепи развязывающего диода, оптопара VU37 или транзистор VT42.' AS description, 0 AS safety
    UNION ALL SELECT 'b4' AS code, 'Неисправен элемент гальванической развязки столбца Stb4' AS title, 'Элемент развязки столбца Stb4 (604) на плате ПУ постоянно закрыт, приказы этого столбца не регистрируются. Руководство называет возможные причины: оптопара, обрыв в цепи развязывающего диода, оптопара VU37 или транзистор VT42.' AS description, 0 AS safety
    UNION ALL SELECT 'b5' AS code, 'Неисправен элемент гальванической развязки столбца Stb5' AS title, 'Элемент развязки столбца Stb5 (605) на плате ПУ постоянно закрыт, лифт отключается. Руководство называет возможные причины: оптопара, обрыв в цепи развязывающего диода, оптопара VU37 или транзистор VT42.' AS description, 0 AS safety
    UNION ALL SELECT 'b6' AS code, 'Неисправен элемент гальванической развязки столбца Stb6' AS title, 'Элемент развязки столбца Stb6 (606) на плате ПУ постоянно закрыт, лифт отключается. Руководство называет возможные причины: оптопара, обрыв в цепи развязывающего диода, оптопара VU37 или транзистор VT42.' AS description, 0 AS safety
    UNION ALL SELECT 'b7' AS code, 'Неисправен элемент гальванической развязки столбца Stb7' AS title, 'Элемент развязки столбца Stb7 (607) на плате ПУ постоянно закрыт, лифт отключается. Руководство называет возможные причины: оптопара, обрыв в цепи развязывающего диода, оптопара VU37 или транзистор VT42.' AS description, 0 AS safety
    UNION ALL SELECT 'b8' AS code, 'Неисправен элемент гальванической развязки столбца Stb8' AS title, 'Элемент развязки столбца Stb8 (608) на плате ПУ постоянно закрыт, лифт отключается. Руководство называет возможные причины: оптопара, обрыв в цепи развязывающего диода, оптопара VU37 или транзистор VT42.' AS description, 0 AS safety
    UNION ALL SELECT 'b9' AS code, 'Неисправна FLASH-память платы ПУ' AS title, 'При включении платы ПУ программа проверяет параметры во FLASH-памяти. Код появляется, если параметра нет или ни одно из его значений не лежит в допустимом диапазоне. УЛ блокирует работу лифта и выключает реле К1 «АВАРИЯ». Для восстановления: войти в функцию F7 и задать параметру С5 значение 1 (заводские значения). Проверка памяти: задать нестандартные значения параметров и переключить тумблер SA1 «Сеть», новые значения должны сохраниться.' AS description, 0 AS safety
) v
WHERE c.name = 'УЛ ФБИР.484430.013 (ГОСТ 33984.1, автоматические двери)'
ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), is_safety_related = VALUES(is_safety_related), source = VALUES(source);

